import{_ as t,o as s,c as o,a4 as a}from"./chunks/framework.Jm0b7rri.js";const m=JSON.parse('{"title":"xs-from-rsync(7)","description":"What stays the same, what changes, and how to switch an existing rsync habit or script to xs.","frontmatter":{"title":"xs-from-rsync(7)","description":"What stays the same, what changes, and how to switch an existing rsync habit or script to xs.","manual":"xs-from-rsync(7)","manualName":"Coming from rsync","sectionNumber":"7"},"headers":[],"relativePath":"migration.md","filePath":"migration.md"}'),r={name:"migration.md"};function d(n,e,c,i,l,h){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="xs-from-rsync-7" tabindex="-1">xs-from-rsync(7) <a class="header-anchor" href="#xs-from-rsync-7" aria-label="Permalink to &quot;xs-from-rsync(7)&quot;">​</a></h1><div class="manual-deck"><strong>Coming from rsync</strong><p>What stays the same, what changes, and how to switch an existing rsync habit or script to xs.</p></div><h2 id="summary" tabindex="-1">THE SHORT VERSION <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;THE SHORT VERSION {#summary}&quot;">​</a></h2><p>xs takes rsync’s command line. Trailing-slash rules, <code>-a</code>, filters, <code>--delete</code>, itemized output and exit codes all mean what they mean in rsync. Options it does not implement are handed to a real rsync automatically, so an existing command keeps working. You need <code>xs</code> on both machines for native remote transfers; without it, those transfers fall back to rsync too.</p><div class="example-caption">Try it on one command before changing anything else</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-ani</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#858585;">      # preview: same itemize codes as rsync</span></span>
<span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#858585;">                # then run it</span></span></code></pre></div><aside class="manual-note"><span>ALIAS</span><p><code>alias rsync=xs</code> works for interactive use. In scripts, call <code>xs</code> by name instead, so it is clear which tool ran and fallback stays visible. Fallback runs whichever <code>rsync</code> is first on <code>PATH</code>. An alias does not change that, because aliases do not apply to the executed program.</p></aside><h2 id="shapes" tabindex="-1">YOUR COMMANDS <a class="header-anchor" href="#shapes" aria-label="Permalink to &quot;YOUR COMMANDS {#shapes}&quot;">​</a></h2><p>These are the invocation shapes xs was built around, taken from real shell history and project scripts.</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">If you run</th><th scope="col">With xs</th></tr></thead><tbody><tr><td><code>rsync -axhP DIR DEST</code></td><td>Works as is. <code>-x</code> stays on one filesystem; <code>-P</code> resumes interrupted files from a verified prefix; progress is xs’s live display. <code>-h</code> uses decimal units, <code>-hh</code> binary.</td></tr><tr><td><code>rsync -az[P] SRC DEST</code>, with <code>--exclude</code></td><td>Works as is, locally or over ssh. <code>-z</code> uses zstd; filters keep rsync’s first-match rules.</td></tr><tr><td><code>rsync -e &quot;ssh -i KEY&quot; …</code></td><td>Works as is. Quoting in <code>-e</code>, keys and passphrase prompts behave as with rsync.</td></tr><tr><td><code>rsync -az --delete --out-format=&#39;%i %n&#39;</code> in a script</td><td>Works, with stable output: file lines are sorted when stdout is not a terminal. <code>%b</code> counts file bytes rather than protocol bytes.</td></tr><tr><td><code>rsync -rlptz</code>, <code>--info=progress2</code></td><td>Works. <code>--info=progress2</code> prints rsync’s line shape on a pipe; <code>--progress=json</code> is the structured alternative.</td></tr></tbody></table></div><h2 id="differences" tabindex="-1">WHAT IS DIFFERENT <a class="header-anchor" href="#differences" aria-label="Permalink to &quot;WHAT IS DIFFERENT {#differences}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Area</th><th scope="col">rsync</th><th scope="col">xs</th></tr></thead><tbody><tr><td>Wire protocol</td><td>rsync protocol; works with rsync daemons</td><td>Its own protocol; xs on both ends. Daemon URLs (<code>host::module</code>, <code>rsync://</code>) go to rsync.</td></tr><tr><td>New files</td><td>Temporary file, then rename</td><td>The same by default. <code>--no-atomic</code> writes them directly.</td></tr><tr><td>Progress</td><td>Off unless <code>-P</code>/<code>--progress</code></td><td>On whenever stderr is a terminal; off in scripts. <code>--no-progress</code> or <code>XSYNC_PROGRESS=0</code> turns it off.</td></tr><tr><td>File-line order on a pipe</td><td>As transferred</td><td>Sorted by path at the end of the run.</td></tr><tr><td><code>%b</code> in <code>--out-format</code></td><td>Protocol bytes</td><td>File-content bytes before compression.</td></tr><tr><td>Local copies on APFS</td><td>Byte copies</td><td>Copy-on-write clones, which can carry xattrs, ACLs and extra times. <code>--no-clone</code> copies bytes.</td></tr><tr><td><code>-z</code> on a local copy</td><td>Compresses and decompresses</td><td>Does nothing.</td></tr><tr><td>Symlinks inside the destination</td><td>Followed for directories with <code>--keep-dirlinks</code></td><td>Never followed by writes, metadata changes or cleanup; <code>--keep-dirlinks</code> goes to rsync.</td></tr><tr><td><code>-E</code></td><td>Executability (Apple’s system rsync: extended attributes)</td><td>Executability. Use <code>-X</code> for attributes.</td></tr><tr><td>Unsupported options</td><td>—</td><td>Handed to rsync with a notice; with <code>--no-fallback</code>, exit 1.</td></tr></tbody></table></div><p>The <a href="compatibility.html">compatibility page</a> lists the details, and <a href="options.html#delegated">delegated options</a> lists exactly which options go to rsync.</p><h2 id="scripts" tabindex="-1">SWITCHING A SCRIPT <a class="header-anchor" href="#scripts" aria-label="Permalink to &quot;SWITCHING A SCRIPT {#scripts}&quot;">​</a></h2><ol><li>Replace <code>rsync</code> with <code>xs</code> and run the script once with <code>-n</code> added. Compare the itemized output with rsync’s; it uses the same codes (<a href="itemize.html">itemize reference</a>).</li><li>Look for <code>xs: falling back to rsync:</code> on stderr. Each notice names the option or condition that caused it.</li><li>Decide whether fallback is acceptable. If the script must be native, add <code>--no-fallback</code> or set <code>XSYNC_FALLBACK=0</code>; it then fails before writing instead of silently running rsync.</li><li>Pin personal defaults out of the script’s way with <code>XSYNC_CONFIG=&#39;&#39; XSYNC_OPTS=&#39;&#39;</code> if your interactive defaults should not apply (<a href="environment.html#deterministic">control defaults explicitly</a>).</li><li>Keep checking the exit status. The codes are rsync’s: 23 for a partial transfer, 24 for vanished files, 25 for the deletion limit, and so on (<a href="exit-status.html">exit status</a>).</li></ol><h2 id="speed" tabindex="-1">SPEED EXPECTATIONS <a class="header-anchor" href="#speed" aria-label="Permalink to &quot;SPEED EXPECTATIONS {#speed}&quot;">​</a></h2><p>xs is built for trees of many small files and for local copies on one APFS volume, where clones and parallel workers help most. Over a 1 Gb/s network, uncompressed transfers are limited by the link, and both tools take about the same time; <code>-z</code> helps xs more. Some cases are slower today. See <a href="performance.html">performance</a> for measured numbers, losses included.</p>`,17)])])}const y=t(r,[["render",d]]);export{m as __pageData,y as default};
